interface MuxUICollectionItem {
  id?: string;
  key?: string;
  label?: React.ReactNode;
  value?: string;
  textValue?: string;
  disabled?: boolean;
  [key: string]: unknown;
}

type VirtualizerGridProps = Pick<VirtualizerOwnProps, 'minItemWidth' | 'maxItemWidth' | 'estimatedItemHeight' | 'maxColumns' | 'overscan'> & {
  layout: 'grid';
  children: React.ReactElement;
  'aria-label'?: never;
  'aria-labelledby'?: never;
  items?: never;
  height?: never;
  itemHeight?: never;
  disabled?: never;
  onScroll?: never;
  className?: never;
  style?: never;
};

type VirtualizerOwnProps = {
  layout?: 'stack' | 'grid';
  items?: MuxUIItems;
  height?: number;
  itemHeight?: number;
  overscan?: number;
  disabled?: boolean;
  onScroll?: React.UIEventHandler<HTMLDivElement>;
  children?: React.ReactElement;
  minItemWidth?: number;
  maxItemWidth?: number;
  estimatedItemHeight?: number;
  maxColumns?: number;
};

type VirtualizerStackProps = MuxUIAriaLabel & Pick<VirtualizerOwnProps, 'items' | 'height' | 'itemHeight' | 'overscan' | 'disabled' | 'onScroll'> & {
  layout?: 'stack';
  className?: string;
  style?: React.CSSProperties;
  children?: never;
  minItemWidth?: never;
  maxItemWidth?: never;
  estimatedItemHeight?: never;
  maxColumns?: never;
};
